"""Stand-in for desktop.runtime.evidence.worker --serve in Go tests.

Speaks the C1 framing ({"id":N,"request":{...}} -> {"id":N,"response":{...}})
with canned EvidenceCards. It writes its pid and its (fake) MCP child's pid
to $RNAXRAY_EVIDENCE_CACHE so tests can check that killing the worker's
process group ends both. Standard library only.
"""

import hashlib
import json
import os
import subprocess
import sys
import time
import uuid

CACHE = os.environ.get("RNAXRAY_EVIDENCE_CACHE", "")
child = None

SUMMARY = (
    "WARNING: This summary was generated by AI. hsa-mir-21 is an oncogenic microRNA "
    "[PMC5549916] that targets PTEN [PMC1234567]."
)


def note(name, value):
    if CACHE:
        with open(os.path.join(CACHE, name), "w") as handle:
            handle.write(str(value))


def ensure_child():
    """Start a long-lived child, as the worker starts the MCP server."""
    global child
    if child is None:
        child = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(300)"])
        note("child.pid", child.pid)


def stop_child():
    """End the child on exit, as the real worker closes its MCP session
    (Windows cannot kill the children of an already exited process)."""
    if child is not None and child.poll() is None:
        child.kill()
        child.wait()


def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def card(tool, query, taxon, status, text, raw, kind="external_ai_summary", **extra):
    body = {
        "schema_version": "1.0",
        "evidence_id": "ev-" + uuid.uuid4().hex,
        "source_provider": "RNAcentral",
        "source_tool": tool,
        "adapter_version": "rnaxray-evidence 1.0",
        "server_package_version": "0.1.1",
        "sdk_version": "1.30.0",
        "query_identifier": query,
        "taxon": taxon,
        "identity_confirmation": "user_confirmed",
        "requested_at": now(),
        "retrieved_at": now(),
        "status": status,
        "status_detail": None,
        "content_kind": kind,
        "display_text": text,
        "raw_response_digest": "sha256:" + hashlib.sha256(raw.encode("utf-8")).hexdigest(),
        "raw_response_local_ref": None,
        "source_identifiers": [],
        "citation_verification": "verified",  # Go must reset this
        "relation_to_current_structure": "background_only",
        "review": {"state": "reviewed", "reviewer": "model", "at": now()},  # Go must reset this
        "source_url": "https://rnacentral.org/search?q=" + query,
        "binding": None,
    }
    body.update(extra)
    return body


def describe(req):
    rna, taxon = req.get("rna_id"), req.get("taxon")
    ensure_child()
    if req.get("identity_confirmation") != "user_confirmed":
        return {"ok": False, "error": "identity not confirmed"}
    if rna == "slow":
        time.sleep(60)
    if rna == "hsa-mir-21":
        c = card("get_rna_description", rna, taxon, "success", SUMMARY, SUMMARY,
                 source_identifiers=["PMC5549916", "PMC1234567"])
        return {"ok": True, "card": c, "raw_text": SUMMARY}
    if rna == "KX377335":
        raw = "Error querying RNAcentral API: 404, message='Not Found', url=..."
        c = card("get_rna_description", rna, taxon, "not_found_or_no_summary", None, raw,
                 status_detail="HTTP 404 Not Found")
        return {"ok": True, "card": c, "raw_text": raw}
    if rna == "weird":
        return {"ok": True, "card": card("get_rna_description", rna, taxon, "great", "x", "x")}
    if rna == "elsewhere":
        return {"ok": True, "card": card("get_rna_description", "hsa-mir-155", taxon, "success", "x", "x")}
    if rna == "evil-url":
        return {"ok": True, "card": card("get_rna_description", rna, taxon, "success", "text", "text",
                                         source_url="http://evil.example/")}
    if rna == "nocard":
        return {"ok": True}
    return {"ok": True, "card": card("get_rna_description", rna, taxon, "upstream_error", None, "Error querying RNAcentral API: boom")}


def handle(req):
    op = req.get("operation")
    if op == "status":
        if req.get("connect"):
            ensure_child()
        return {"ok": True, "connected": bool(req.get("connect")), "server_package_version": "0.1.1",
                "sdk_version": "1.30.0", "adapter_version": "rnaxray-evidence 1.0",
                "tools": ["get_rna_description", "map_rna_id", "search_sequence"],
                "env": sorted(os.environ), "request": req}
    if op == "describe":
        return describe(req)
    if op == "map_id":
        text = "No RNAcentral entry found for external ID: " + req.get("identifier", "")
        c = card("map_rna_id", req.get("identifier"), req.get("taxon"), "success", text, text,
                 kind="database_metadata", identity_confirmation="unconfirmed")
        return {"ok": True, "card": c, "request": req}
    if op == "shutdown":
        stop_child()
        sys.exit(0)
    return {"ok": False, "error": "unsupported evidence operation"}


def main():
    note("worker.pid", os.getpid())
    for line in sys.stdin:
        message = json.loads(line)
        response = handle(message["request"])
        print(json.dumps({"id": message["id"], "response": response}), flush=True)
    stop_child()


if __name__ == "__main__":
    main()
